#!/usr/bin/env node
/**
 * VEXTREME - lib/build-page-health.js
 *
 * Builds one deterministic page-capability projection for Archives and the
 * Terrain Map. It joins existing registries and audits; it does not introduce
 * a second hand-maintained page inventory.
 *
 * LATTICE:BEGIN — generated by lib/build-lattice-headers.js from docs/lattice-map.json. Do not hand-edit; edit the JSON and regenerate.
 *   role      : joins existing page registries, runtime audits, localization identity, analysis, and screenshot evidence into one deterministic per-page capability projection
 *   reads     : pages∕*.html (runtime tags, data-i18n bindings, authored theme styles)
 *               data/nodes.json (arc placement)
 *               data/strings/compiled/manifest.json (translation coverage)
 *               data/analysis-index.json (analysis indexing)
 *               dist∕*.js (God Script FAB and analysis delivery)
 *               docs/screenshots∕*.png (evidence presence)
 *               config/institutional-surfaces.json (institutional page classification and intentional record-runtime exclusions)
 *               lib/screenshot-evidence.js (shared legacy and locale/theme/viewport evidence discovery)
 *               lib/audit-pages.js (page inventory and God Script wiring)
 *               lib/audit-nav.js (navigation classification)
 *               lib/audit-fab.js (theme ownership and opt-out classification)
 *               data/screenshot-evidence-assets.json (pinned Vextreme-Assets fallback screenshot evidence projection; local docs/screenshots remain priority)
 *   writes    : data/page-health.json
 *   loaded-by : manual run: node lib/build-page-health.js
 *               .github/workflows/build-index.yml (before Archives and Terrain)
 *               tests/helpers/prereqs.js
 *               tests/44-page-health.test.js
 *               lib/check-description-freshness.js (metaDescriptionText only)
 *   tested-by : tests/44-page-health.test.js
 *
 *   CHANGE MAP — if you touch X here, also check:
 *     data/page-health.json schema changed:
 *       - lib/build-archives.js (page-health badges and summary)
 *       - lib/build-terrain-map.js (content node status and capability payload)
 *       - pages/terrain-map.html (content detail panel)
 *       - tests/44-page-health.test.js
 *     health severity rules changed:
 *       - Archives summary counts and Terrain content status colors both change
 *     metaDescriptionText() signature or export removed:
 *       - lib/check-description-freshness.js (imports it directly, not through the page-health projection)
 *     pinned Assets screenshot projection changed:
 *       - lib/screenshot-evidence.js (Assets record normalization + local-first merge semantics)
 *       - tests/44-page-health.test.js (remote fallback without weakening institutional matrix proof)
 *       - data/page-health.json generated projection
 * LATTICE:END
 */

'use strict';

const fs = require('fs');
const path = require('path');
const institutionalRegistry = require('../config/institutional-surfaces.json');
const { SKIP_PAGES, getPageSlugs, isWiredToGodScript } = require('./audit-pages');
const { getNavReport } = require('./audit-nav');
const { managesOwnDataTheme, hasThemeOptOut } = require('./audit-fab');
const { findScreenshotEvidence, findAssetScreenshotEvidence, mergeScreenshotEvidence, exactMatrixEvidence } = require('./screenshot-evidence');

const ROOT = path.join(__dirname, '..');
const PAGES_DIR = path.join(ROOT, 'pages');
const DIST_DIR = path.join(ROOT, 'dist');
const SCREENSHOTS_DIR = path.join(ROOT, 'docs', 'screenshots');
const OUT_PATH = path.join(ROOT, 'data', 'page-health.json');

const GENERATED_READ_ALOUD_OWNERS = Object.freeze({
  'build-health': 'lib/build-archives.js',
  'ecosystem-hub': 'lib/build-ecosystem-hub.js',
  'roles-index': 'lib/build-roles-page.js',
  'vextreme-demo': 'lib/build-demo.js',
  'ai-practitioner-tools': 'tools/vex-content-forge/project_group_homes.js',
  'direct-contact': 'tools/vex-content-forge/project_group_homes.js',
});

function generatedReadAloudOwners(root = ROOT) {
  const out = {};
  for (const [slug, owner] of Object.entries(GENERATED_READ_ALOUD_OWNERS)) {
    const source = path.join(root, owner);
    if (fs.existsSync(source) && fs.readFileSync(source, 'utf8').includes('fab-read-aloud.js')) {
      out[slug] = 'generated-owner';
    }
  }
  return out;
}

function readJson(relPath, fallback) {
  const file = path.join(ROOT, relPath);
  return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : fallback;
}

function pageI18nKeys(html) {
  const keys = new Set();
  const re = /\bdata-i18n(?:-alt|-aria)?=["']([^"']+)["']/g;
  let match;
  while ((match = re.exec(html))) keys.add(match[1]);
  return [...keys].sort();
}

function languageCoverage(keys, manifest) {
  const languages = new Set(['en']);
  for (const key of keys) {
    const entry = manifest[key];
    for (const lang of (entry && entry.langs) || []) languages.add(lang);
  }

  const coverage = {};
  for (const lang of [...languages].sort()) {
    const translated = keys.filter((key) => manifest[key] && manifest[key].langs.includes(lang)).length;
    coverage[lang] = {
      translated,
      total: keys.length,
      state: keys.length === 0 ? 'none' : (translated === keys.length ? 'full' : (translated > 0 ? 'partial' : 'none')),
    };
  }
  return coverage;
}

function screenshotLanguages(slug, files) {
  const evidence = findScreenshotEvidence(files)[slug] || [];
  return screenshotLanguagesFromEvidence(evidence);
}

function matrixScreenshotEvidence(slug, files) {
  return matrixScreenshotEvidenceFromRecords(findScreenshotEvidence(files)[slug] || []);
}

function screenshotLanguagesFromEvidence(evidence) {
  return [...new Set((evidence || []).map(record => record.locale))].sort();
}

function matrixScreenshotEvidenceFromRecords(evidence) {
  return exactMatrixEvidence(evidence);
}

function hasInstitutionalThemeEvidence(slug, entry, files) {
  const requiredThemes = (entry && entry.evidence && entry.evidence.themes) || [];
  const observedThemes = new Set(matrixScreenshotEvidence(slug, files).map(record => record.theme));
  return requiredThemes.length > 0 && requiredThemes.every(theme => observedThemes.has(theme));
}

function hasInstitutionalThemeEvidenceFromRecords(entry, evidence) {
  const requiredThemes = (entry && entry.evidence && entry.evidence.themes) || [];
  const observedThemes = new Set(matrixScreenshotEvidenceFromRecords(evidence).map(record => record.theme));
  return requiredThemes.length > 0 && requiredThemes.every(theme => observedThemes.has(theme));
}

function metaDescriptionText(html) {
  const tags = html.match(/<meta\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const name = tag.match(/\bname=["']([^"']*)["']/i);
    if (!name || name[1].toLowerCase() !== 'description') continue;
    const content = tag.match(/\bcontent=["']([^"']*)["']/i);
    return content ? content[1].trim() : '';
  }
  return '';
}

function hasVisibleThemeStyles(html) {
  return /\[data-theme=["']?(?:light|dark)["']?\]/.test(html) ||
    /:root\[data-theme=["']?(?:light|dark)["']?\]/.test(html) ||
    /prefers-color-scheme\s*:\s*(?:light|dark)/.test(html);
}

function fabDelivery(html, distJs, wired) {
  const shell = /lib\/shell\.js/.test(html);
  const disabled = /\bfab\s*:\s*false/.test(html);
  const handAuthored = /widgets\/[^"']*fab[^"']*\.js/.test(html);
  const godScriptFab = wired && (distJs.includes('feature: spiral-fab') || distJs.includes('vex-fab.js'));
  if (disabled) return 'disabled';
  if (shell) return 'shell';
  if (godScriptFab) return 'god-script';
  if (handAuthored) return 'page-owned';
  return 'missing';
}

function hasReadableContent(html) {
  const visible = String(html || '')
    .replace(/<(script|style|noscript|template)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[^]*?-->/g, ' ');
  return /<(?:h[1-6]|p|li|blockquote|figcaption|pre|td|th)\b[^>]*>[\s\S]*?\S[\s\S]*?<\/(?:h[1-6]|p|li|blockquote|figcaption|pre|td|th)>/i.test(visible);
}

function readAloudApplicable(slug, html) {
  if (!String(html || '').trim()) return false;
  const skipReason = String(SKIP_PAGES[slug] || '');
  if (/dev fixture/i.test(skipReason)) return false;
  if (/<meta\b[^>]*name=["']robots["'][^>]*content=["'][^"']*noindex/i.test(html) && /location\.replace\(/.test(html)) return false;
  return hasReadableContent(html);
}

function readAloudDelivery(html, distJs, wired, declaredOwner = null) {
  if (/fabWidgets\s*:\s*\{[^}]*readAloud\s*:\s*false/.test(html)) return 'disabled';
  if (declaredOwner) return declaredOwner;
  if (/widgets\/fab-read-aloud\.js/.test(html)) return 'page-owned';
  if (/lib\/shell\.js/.test(html)) return 'shell';
  if (wired && (distJs.includes('fab-read-aloud.js') || distJs.includes('feature: read-aloud'))) return 'god-script';
  if (/widgets\/vex-institutional\.js/.test(html)) return 'institutional-shared';
  return 'missing';
}

function computeHealth(page, institutionalEntry = null) {
  const blockers = [];
  const gaps = [];
  const institutional = page.surface && page.surface.kind === 'institutional';
  const institutionalMode = institutionalEntry && institutionalEntry.runtime
    ? institutionalEntry.runtime.mode
    : null;
  const groupHome = page.surface && page.surface.kind === 'group-home';
  const nonRecordSurface = institutional || groupHome;
  if (!page.navigation.navigable && !groupHome) blockers.push('isolated');
  if (institutional && page.runtime.shell && institutionalMode !== 'shell-context') blockers.push('institutional-shell');
  if (institutional && institutionalMode === 'shell-context' && !page.runtime.shell) blockers.push('institutional-shell-missing');
  if (institutional && page.runtime.godScript) blockers.push('institutional-god-script');
  if (!nonRecordSurface && page.fab.delivery === 'missing') gaps.push('fab');
  if (page.readAloud.applicable && ['missing', 'disabled'].includes(page.readAloud.delivery)) gaps.push('read-aloud');
  if (!nonRecordSurface && page.placement.state !== 'sorted') gaps.push(page.placement.state);
  if (page.identity.keyCount === 0) gaps.push('identity');
  if (page.evidence.screenshotLanguages.length === 0) gaps.push('screenshot');
  if (page.theme.control !== 'none' && !page.theme.visibleStyles) gaps.push('theme-effect');
  return {
    state: blockers.length ? 'critical' : (gaps.length ? 'attention' : 'healthy'),
    blockers,
    gaps,
  };
}

function buildPageHealth(inputs) {
  const nodesBySlug = Object.fromEntries((inputs.nodes || []).map((node) => [node.slug, node]));
  const navBySlug = Object.fromEntries((inputs.navRows || []).map((row) => [row.slug, row]));
  const screenshotEvidenceBySlug = inputs.screenshotEvidenceBySlug ||
    mergeScreenshotEvidence(
      findScreenshotEvidence(inputs.screenshotFiles || []),
      findAssetScreenshotEvidence(inputs.assetScreenshotProjection || null)
    );
  const pages = {};

  for (const slug of inputs.pageSlugs.slice().sort()) {
    const html = inputs.htmlBySlug[slug] || '';
    const distJs = inputs.distBySlug[slug] || '';
    const node = nodesBySlug[slug];
    const keys = pageI18nKeys(html);
    const wired = Boolean(inputs.wiredBySlug[slug]);
    const nav = navBySlug[slug] || { staticHubLinks: 0, hasShellJs: false, hasFabNav: false, navigable: false };
    const institutionalEntry = (inputs.institutionalSurfaces || {})[slug] || null;
    const institutional = Boolean(institutionalEntry);
    const groupHome = /<html\b[^>]*data-vex-surface=["']group-home["']/i.test(html);
    const readAloudIsApplicable = readAloudApplicable(slug, html);
    const readAloudOwner = (inputs.readAloudOwnedBySlug || {})[slug] || null;
    const observedFabDelivery = fabDelivery(html, distJs, wired);
    const projectedFabDelivery = observedFabDelivery === 'missing' && readAloudOwner === 'generated-owner'
      ? 'page-owned'
      : observedFabDelivery;
    const themeOwned = managesOwnDataTheme(html);
    const themeOptOut = hasThemeOptOut(html);
    const screenshotEvidence = screenshotEvidenceBySlug[slug] || [];
    const matrixEvidence = matrixScreenshotEvidenceFromRecords(screenshotEvidence);

    const page = {
      slug,
      title: (node && node.title) || slug,
      ...(institutional ? { surface: { kind: 'institutional', state: institutionalEntry.state } } :
        (groupHome ? { surface: { kind: 'group-home', state: 'active' } } : {})),
      placement: {
        state: institutional ? 'institutional' : (groupHome ? 'group-home' : (!node ? 'uncurated' : ((node.arcKeys || []).length ? 'sorted' : 'unsorted'))),
        arcKeys: (node && node.arcKeys) || [],
      },
      runtime: {
        shell: nav.hasShellJs,
        godScript: wired,
      },
      navigation: {
        navigable: nav.navigable,
        staticHubLinks: nav.staticHubLinks,
        shell: nav.hasShellJs,
        fab: nav.hasFabNav,
      },
      fab: { delivery: (institutional || groupHome) ? 'not-applicable' : projectedFabDelivery },
      readAloud: {
        applicable: readAloudIsApplicable,
        delivery: readAloudIsApplicable ? readAloudDelivery(html, distJs, wired, readAloudOwner) : 'not-applicable',
      },
      theme: {
        control: themeOwned ? 'page-owned' : (nav.hasShellJs && !themeOptOut ? 'shared' : 'none'),
        visibleStyles: institutional
          ? hasInstitutionalThemeEvidenceFromRecords(institutionalEntry, screenshotEvidence)
          : hasVisibleThemeStyles(html),
      },
      identity: {
        keyCount: keys.length,
        languages: languageCoverage(keys, inputs.manifest || {}),
      },
      analysis: {
        indexed: Boolean(inputs.analysisPages && inputs.analysisPages[slug]),
        control: /fab-analysis\.js/.test(html) || /feature:\s*analysis/.test(distJs),
      },
      evidence: {
        screenshotLanguages: screenshotLanguagesFromEvidence(screenshotEvidence),
        ...(matrixEvidence.length ? { screenshotFiles: matrixEvidence.map(record => record.path) } : {}),
      },
      discovery: {
        metaDescription: metaDescriptionText(html),
      },
    };
    page.health = computeHealth(page, institutionalEntry);
    pages[slug] = page;
  }

  const rows = Object.values(pages);
  return {
    schemaVersion: 1,
    summary: {
      total: rows.length,
      healthy: rows.filter((page) => page.health.state === 'healthy').length,
      attention: rows.filter((page) => page.health.state === 'attention').length,
      critical: rows.filter((page) => page.health.state === 'critical').length,
      sorted: rows.filter((page) => page.placement.state === 'sorted').length,
      withFab: rows.filter((page) => !['missing', 'disabled', 'not-applicable'].includes(page.fab.delivery)).length,
      readAloudApplicable: rows.filter((page) => page.readAloud.applicable).length,
      withReadAloud: rows.filter((page) => page.readAloud.applicable && !['missing', 'disabled'].includes(page.readAloud.delivery)).length,
      missingReadAloud: rows.filter((page) => page.readAloud.applicable && ['missing', 'disabled'].includes(page.readAloud.delivery)).length,
      withIdentity: rows.filter((page) => page.identity.keyCount > 0).length,
      withScreenshots: rows.filter((page) => page.evidence.screenshotLanguages.length > 0).length,
      withMetaDescription: rows.filter((page) => page.discovery.metaDescription).length,
    },
    pages,
  };
}

function loadInputs() {
  const pageSlugs = getPageSlugs();
  const htmlBySlug = {};
  const distBySlug = {};
  const wiredBySlug = {};
  for (const slug of pageSlugs) {
    htmlBySlug[slug] = fs.readFileSync(path.join(PAGES_DIR, `${slug}.html`), 'utf8');
    const distPath = path.join(DIST_DIR, `vextreme-${slug}.js`);
    distBySlug[slug] = fs.existsSync(distPath) ? fs.readFileSync(distPath, 'utf8') : '';
    wiredBySlug[slug] = isWiredToGodScript(slug);
  }
  return {
    pageSlugs,
    htmlBySlug,
    distBySlug,
    wiredBySlug,
    navRows: getNavReport().rows,
    nodes: readJson('data/nodes.json', []),
    manifest: readJson('data/strings/compiled/manifest.json', {}),
    analysisPages: readJson('data/analysis-index.json', {}).pages || {},
    screenshotFiles: fs.existsSync(SCREENSHOTS_DIR) ? fs.readdirSync(SCREENSHOTS_DIR) : [],
    assetScreenshotProjection: readJson('data/screenshot-evidence-assets.json', null),
    institutionalSurfaces: institutionalRegistry.surfaces,
    readAloudOwnedBySlug: generatedReadAloudOwners(),
  };
}

if (require.main === module) {
  const result = buildPageHealth(loadInputs());
  fs.writeFileSync(OUT_PATH, JSON.stringify(result, null, 2) + '\n');
  console.log(`[build-page-health] ${result.summary.total} pages: ${result.summary.healthy} healthy, ${result.summary.attention} attention, ${result.summary.critical} critical`);
  console.log(`  output: ${OUT_PATH}`);
}

module.exports = {
  pageI18nKeys,
  languageCoverage,
  screenshotLanguages,
  matrixScreenshotEvidence,
  screenshotLanguagesFromEvidence,
  matrixScreenshotEvidenceFromRecords,
  hasInstitutionalThemeEvidence,
  hasInstitutionalThemeEvidenceFromRecords,
  hasVisibleThemeStyles,
  metaDescriptionText,
  fabDelivery,
  hasReadableContent,
  readAloudApplicable,
  readAloudDelivery,
  generatedReadAloudOwners,
  computeHealth,
  buildPageHealth,
  loadInputs,
};

// [VXG RealForever]
